"""Randomized differential test of the pattern engine vs Python re."""
import random, re, sys
sys.path.insert(0, '/workspace/project/src')
import eywa.regex as R

def to_py(node):
    if isinstance(node, R.Empty):
        return ""
    if isinstance(node, R.Lit):
        return re.escape(chr(node.cp))
    if isinstance(node, R.Class):
        parts = []
        for (lo, hi) in node.ranges:
            parts.append(re.escape(chr(lo)) + "-" + re.escape(chr(hi)) if lo != hi else re.escape(chr(lo)))
        return "[" + "".join(parts) + "]"
    if isinstance(node, R.Seq):
        return "(" + "".join(to_py(p) for p in node.parts) + ")"
    if isinstance(node, R.Alt):
        return "(" + "|".join(to_py(a) for a in node.alts) + ")"
    if isinstance(node, R.Star):
        return "(" + to_py(node.inner) + ")*"
    raise AssertionError

ALPHA = "ab-c[]()|*\\x "
def rand_atom(depth):
    r = random.random()
    if r < 0.3 or depth > 3:
        return random.choice(ALPHA)
    if r < 0.5:
        lo = random.choice("ac-")
        hi = random.choice("bdz")
        if ord(lo) > ord(hi):
            lo, hi = hi, lo
        return "[%s]" % (lo + ("-" + hi if random.random() < 0.6 else ""))
    if r < 0.75:
        return "(" + rand_seq(depth + 1) + ")"
    return rand_atom(depth) + "*"

def rand_seq(depth):
    return "".join(rand_atom(depth) for _ in range(random.randint(0, 3)))

def rand_pattern():
    return "|".join(rand_seq(0) for _ in range(random.randint(1, 2)))

random.seed(99)
checked = 0
for trial in range(3000):
    text = rand_pattern()
    try:
        node = R.parse_pattern(text)
    except Exception as e:
        print("PARSE ERR", repr(text), e)
        sys.exit(1)
    py = to_py(node)
    cre = re.compile(py)
    pat = R.Pattern(node)
    s = "".join(random.choice("abc-[]()*\\|") for _ in range(random.randint(0, 6)))
    a = pat.match(s)
    b = cre.fullmatch(s) is not None
    if a != b:
        print("MISMATCH", repr(text), repr(py), repr(s), a, b)
        sys.exit(1)
    checked += 1
print("T11 OK", checked, "cases")
